function integer transform() {
    // Copy fields from CustomerDetails (input 0)
    $out.0.client_id    = $in.0.client_id;
    $out.0.full_name    = $in.0.full_name;
    $out.0.primary_email = $in.0.email;        // nullable allowed
    $out.0.country_code = $in.0.country_code;
    $out.0.signup_date  = $in.0.signup_date;

    // Copy fields from SubscriptionStatus (input 1)
    $out.0.plan_code          = $in.1.plan_code;
    $out.0.status             = $in.1.status;
    $out.0.status_updated_at  = $in.1.status_updated_at;

    // Derive status_group from status
    if (isnull($in.1.status)) {
        $out.0.status_group = "OTHER";
    } else {
        switch ($in.1.status) {
            case "ACTIVE":
            case "TRIALING":
                $out.0.status_group = "ACTIVE";
                break;
            case "CANCELED":
            case "EXPIRED":
                $out.0.status_group = "INACTIVE";
                break;
            default:
                $out.0.status_group = "OTHER";
        }
    }

    // Map nullable boolean auto_renew to string
    if (isnull($in.1.auto_renew)) {
        $out.0.is_auto_renew = "UNKNOWN";
    } else if ($in.1.auto_renew) {
        $out.0.is_auto_renew = "YES";
    } else {
        $out.0.is_auto_renew = "NO";
    }

    return OK;
}
