function integer transform() {
    // Map basic fields
    $out.0.session_id   = $in.0.session_id;
    $out.0.user_id      = $in.0.user_id;
    $out.0.page_url     = $in.1.page_url;
    $out.0.view_ts      = $in.1.view_ts;
    $out.0.country_code = $in.0.country_code;
    $out.0.device_type  = $in.0.device_type;
    $out.0.scroll_depth = $in.1.scroll_depth;

    // Engagement score (non-nullable)
    decimal score = 1.0D;

    if (!isnull($in.1.scroll_depth)) {
        if ($in.1.scroll_depth >= 80) {
            score = score + 2.0D;
        } else if ($in.1.scroll_depth >= 40) {
            score = score + 1.0D;
        }
    }

    if (isnull($in.1.referrer)) {
        score = score + 0.5D;
    }

    $out.0.engagement_score = score;

    // Traffic source (nullable output, but always set)
    string src;
    string ref = $in.1.referrer;

    if (isnull(ref) || isBlank(ref)) {
        src = "Direct";
    } else if (startsWith(ref, "https://search.")) {
        src = "Search";
    } else if (ref ?= "facebook.com" || ref ?= "twitter.com") {
        src = "Social";
    } else {
        src = "Other";
    }

    $out.0.traffic_source = src;

    return OK;
}
