string groupDutySheetRef;
long groupStaffNo;

function void initGroup(DutyAcc acc) {
    acc.first_in_time = null;
    acc.last_out_time = null;
    acc.payroll_punch_total = 0;
    groupDutySheetRef = "";
    groupStaffNo = 0L;
}

function boolean updateGroup(DutyAcc acc) {
    if (acc.payroll_punch_total == 0) {
        groupDutySheetRef = $in.0.duty_sheet_ref;
        groupStaffNo = $in.0.staff_no;
    }

    if (!isnull($in.0.badge_time)) {
        if ($in.0.punch_label == "CLOCK_IN" || $in.0.punch_label == "BAY_ENTRY") {
            if (isnull(acc.first_in_time) || $in.0.badge_time < acc.first_in_time) {
                acc.first_in_time = $in.0.badge_time;
            }
        } else if ($in.0.punch_label == "CLOCK_OUT" || $in.0.punch_label == "YARD_EXIT") {
            if (isnull(acc.last_out_time) || $in.0.badge_time > acc.last_out_time) {
                acc.last_out_time = $in.0.badge_time;
            }
        }

        if (!startsWith($in.0.punch_label, "TEST_")) {
            acc.payroll_punch_total++;
        }
    }

    return false;
}

function boolean finishGroup(DutyAcc acc) {
    return true;
}

function integer updateTransform(integer counter, DutyAcc acc) {
    return SKIP;
}

function integer transform(integer counter, DutyAcc acc) {
    if (counter > 0) return SKIP;

    $out.0.duty_sheet_ref = groupDutySheetRef;
    $out.0.staff_no = groupStaffNo;
    $out.0.shift_start_at = acc.first_in_time;
    $out.0.shift_end_at = acc.last_out_time;
    $out.0.payroll_punch_total = acc.payroll_punch_total;

    if (isnull(acc.first_in_time) || isnull(acc.last_out_time) || acc.last_out_time <= acc.first_in_time) {
        $out.0.payable_minutes = 0;
    } else {
        long diffMillis = dateDiff(acc.last_out_time, acc.first_in_time, millisec);
        $out.0.payable_minutes = long2integer(diffMillis / 60000L);
    }

    return ALL;
}
